611							<input type="email" id="email" name="email" autocomplete="email" inputmode="email" spellcheck="false" autocapitalize="none" required aria-describedby="email-help">
612							<span id="email-error" class="error-message" aria-live="polite"></span>
613							<small id="email-help" class="form-hint">For example, name@example.com</small>
