708		<script>
709			const themeToggle = document.getElementById('theme-toggle');
710			const htmlElement = document.documentElement;
711			const prefersDark = window.matchMedia('(prefers-color-scheme: dark)');
712	
713			const themeColors = { light: '#ffffff', dark: '#121212' };
714			const themeColorMetas = document.querySelectorAll('meta[name="theme-color"]');
715			themeColorMetas.forEach((meta) => {
716				meta.dataset.defaultContent = meta.content;
717			});
718	
719			const updateThemeUI = () => {
720				const forced = htmlElement.dataset.theme;
721				const isDark = forced ? forced === 'dark' : prefersDark.matches;
722				const label = isDark ? 'Switch to light mode' : 'Switch to dark mode';
723				themeToggle.textContent = isDark ? '☀️' : '🌙';
724				themeToggle.setAttribute('aria-label', label);
725				themeToggle.title = label;
726				themeColorMetas.forEach((meta) => {
727					meta.content = forced ? themeColors[forced] : meta.dataset.defaultContent;
728				});
729			};
730	
731			if (themeToggle) {
732				themeToggle.hidden = false;
733				updateThemeUI();
734	
735				themeToggle.addEventListener('click', () => {
736					const systemTheme = prefersDark.matches ? 'dark' : 'light';
737					const current = htmlElement.dataset.theme || systemTheme;
738					const next = current === 'dark' ? 'light' : 'dark';
739					// Choosing the system theme clears the override so the page follows the OS again.
740					try {
741						if (next === systemTheme) {
742							delete htmlElement.dataset.theme;
743							localStorage.removeItem('theme');
744						} else {
745							htmlElement.dataset.theme = next;
746							localStorage.setItem('theme', next);
747						}
748					} catch {}
749					updateThemeUI();
750				});
751	
752				prefersDark.addEventListener('change', () => {
753					if (!htmlElement.dataset.theme) {
754						updateThemeUI();
755					}
756				});
757			}
758	
759			const copyrightYear = document.getElementById('copyright-year');
760			if (copyrightYear) {
761				copyrightYear.textContent = String(new Date().getFullYear());
762			}
763	
764			const messages = [
765				"This update was announced to screen readers!",
766				"Dynamic content updates work with aria-live regions.",
767				"Live regions are essential for accessible web apps.",
768				"Try this with a screen reader like NVDA or JAWS!"
769			];
770			let nextMessage = 0;
771			let count = 0;
772			const announceBtn = document.getElementById('announce');
773			const liveMessage = document.getElementById('live-message');
774			const contactForm = document.getElementById('contact-form');
775			const emailInput = document.getElementById('email');
776			const messageInput = document.getElementById('message');
777			const messageCount = document.getElementById('message-count');
778			const formStatus = document.getElementById('form-status');
779			const countDisplay = document.getElementById('count');
780			const countMessage = document.getElementById('count-message');
781			const decreaseBtn = document.getElementById('decrease');
782			const increaseBtn = document.getElementById('increase');
783			const resetBtn = document.getElementById('reset');
784	
785			const updateCountDisplay = () => {
786				countDisplay.textContent = String(count);
787				countMessage.textContent = `Count is ${count}.`;
788			};
789	
790			if (countDisplay && countMessage) {
791				decreaseBtn?.addEventListener('click', () => {
792					count--;
793					updateCountDisplay();
794				});
795	
796				increaseBtn?.addEventListener('click', () => {
797					count++;
798					updateCountDisplay();
799				});
800	
801				resetBtn?.addEventListener('click', () => {
802					count = 0;
803					updateCountDisplay();
804				});
805			}
806	
807			if (announceBtn && liveMessage) {
808				announceBtn.addEventListener('click', () => {
809					liveMessage.textContent = messages[nextMessage];
810					nextMessage = (nextMessage + 1) % messages.length;
811				});
812			}
813	
814			if (contactForm) {
815				const emailError = document.getElementById('email-error');
816				const submitBtn = contactForm.querySelector('button[type="submit"]');
817				const isSending = () => submitBtn.getAttribute('aria-disabled') === 'true';
818	
819				// Set here rather than in the markup so native validation still works without JavaScript.
820				contactForm.noValidate = true;
821	
822				const setFormStatus = (message, state) => {
823					formStatus.textContent = message;
824					if (state) {
825						formStatus.dataset.state = state;
826					} else {
827						delete formStatus.dataset.state;
828					}
829				};
830	
831				const updateMessageCount = () => {
832					if (messageInput && messageCount) {
833						const remaining = messageInput.maxLength - messageInput.value.length;
834						// Match the page language rather than the browser locale.
835						messageCount.textContent = remaining.toLocaleString(htmlElement.lang);
836					}
837				};
838	
839				messageInput?.addEventListener('input', updateMessageCount);
840				// Browsers may restore field values on back/forward navigation.
841				window.addEventListener('pageshow', updateMessageCount);
842				updateMessageCount();
843	
844				const setEmailError = (message) => {
845					emailError.textContent = message;
846					if (message) {
847						emailInput.setAttribute('aria-invalid', 'true');
848						emailInput.setAttribute('aria-describedby', 'email-error email-help');
849					} else {
850						emailInput.removeAttribute('aria-invalid');
851						emailInput.setAttribute('aria-describedby', 'email-help');
852					}
853				};
854	
855				const validateEmail = () => {
856					let message = '';
857					if (emailInput.validity.valueMissing) {
858						message = 'Enter your email address.';
859					} else if (!emailInput.validity.valid) {
860						message = 'Enter an email address in the format name@example.com.';
861					}
862					setEmailError(message);
863					return !message;
864				};
865	
866				emailInput.addEventListener('blur', () => {
867					if (emailInput.value || emailInput.hasAttribute('aria-invalid')) {
868						validateEmail();
869					}
870				});
871	
872				emailInput.addEventListener('input', () => {
873					if (emailInput.hasAttribute('aria-invalid')) {
874						validateEmail();
875					}
876				});
877	
878				contactForm.addEventListener('input', () => {
879					if (!isSending()) {
880						setFormStatus('');
881					}
882				});
883	
884				contactForm.addEventListener('submit', async (event) => {
885					event.preventDefault();
886					if (isSending()) {
887						return;
888					}
889					setFormStatus('');
890					if (!validateEmail()) {
891						emailInput.focus();
892						return;
893					}
894					const originalText = submitBtn.textContent;
895					// aria-disabled keeps keyboard focus on the button, unlike the disabled attribute.
896					submitBtn.setAttribute('aria-disabled', 'true');
897					submitBtn.setAttribute('aria-busy', 'true');
898					submitBtn.textContent = 'Sending…';
899					setFormStatus('Sending your message…', 'pending');
900					// Read-only rather than disabled so the fields stay focusable while sending.
901					emailInput.readOnly = true;
902					if (messageInput) messageInput.readOnly = true;
903					await new Promise(resolve => setTimeout(resolve, 800));
904					emailInput.readOnly = false;
905					if (messageInput) messageInput.readOnly = false;
906					contactForm.reset();
907					setEmailError('');
908					updateMessageCount();
909					submitBtn.removeAttribute('aria-disabled');
910					submitBtn.removeAttribute('aria-busy');
911					submitBtn.textContent = originalText;
912					setFormStatus("Thanks! This is a demo, so nothing was sent.");
913					emailInput.focus();
914				});
915			}
916		</script>
